function summarize(storage,now){const x=collect(storage,now), out=[];for(const p of DB.patterns){const w=(p.evidenceRules&&p.evidenceRules.windowDays||30)*DAY;const pe=x.ev.filter(e=>e.patternId===p.id);const recent=pe.filter(e=>!e.at||x.now-e.at<=w);const dp=new Set(recent.map(e=>e.uid)).size;const d7=recent.filter(e=>e.at&&x.now-e.at<=7*DAY).length;const prev=recent.filter(e=>e.at&&x.now-e.at>7*DAY&&x.now-e.at<=14*DAY).length;const confirmed=recent.length>=(p.evidenceRules.minEvidence||3)&&dp>=(p.evidenceRules.minDistinctProblems||2);const branches={};for(const e of recent){if(e.branchLabel)branches[e.branchLabel]=(branches[e.branchLabel]||0)+1}const rr=x.rem.filter(r=>r.patternId===p.id),pass=rr.filter(r=>r.passed!==false).length;out.push({id:p.id,name:p.name,priority:p.priority,confirmed,evidenceCount:recent.length,totalEvidence:pe.length,distinctProblems:dp,recent7:d7,previous7:prev,trend:trendLabel(d7,prev),lastAt:Math.max(0,...recent.map(e=>e.at||0)),curriculumLinks:Object.keys(branches).sort((a,b)=>branches[b]-branches[a]).slice(0,4).concat((p.curriculumLinks||[]).filter(z=>!branches[z]).slice(0,2)),studentMessage:p.studentMessage,parentInterpretation:p.parentInterpretation,remediationType:p.remediationType,nextAction:p.nextAction,remediation:{count:rr.length,passed:pass,passRate:rr.length?Math.round(pass/rr.length*100):null,lastAt:Math.max(0,...rr.map(r=>r.at||0))},evidence:recent})}
 out.sort((a,b)=>(b.confirmed-a.confirmed)||((b.recent7*4+b.evidenceCount+b.priority/100)-(a.recent7*4+a.evidenceCount+a.priority/100)));return out}
function activeForAttempt(storage,day,a){const s=readState(storageMap(storage)[String(day)]), cand=classifyAttempt(day,a,s), sum=summarize(storage);let best=null;for(const c of cand){const q=sum.find(z=>z.id===c.patternId&&z.confirmed);if(q&&(!best||q.priority>best.priority||q.evidenceCount>best.evidenceCount))best=q}return best}
function lastWrongFor(storage,day,pid){const s=readState(storageMap(storage)[String(day)]);return [...(s.attempts||[])].reverse().find(a=>a&&a.problemId===pid&&a.correct===false)||null}
function activeForProblem(storage,day,pid){const a=lastWrongFor(storage,day,pid);return a?activeForAttempt(storage,day,a):null}
