function matchesCat(patternId,cat){if(!cat)return false;const t=cat.tags||{};return patternId==='era_position'?t.era:patternId==='entity_activity_link'?t.entity:patternId==='concept_boundary'?t.contrast:patternId==='causal_chain'?t.causal:patternId==='surface_term_memory'?t.term:patternId==='essay_keyword_omission'?t.essay:patternId==='source_cue_application'?t.source:patternId==='prompt_condition_omission'?t.condition:false}
function problemBoost(day,pid,storage){const cat=catFor(day,pid), sums=summarize(storage).filter(x=>x.confirmed);let boost=0;for(const s of sums){if(s.evidence.some(e=>e.uid==='d'+day+'-'+pid))boost=Math.max(boost,7);else if(matchesCat(s.id,cat))boost=Math.max(boost,3)}return {boost,reason:boost?'\uc5f0\uacb0 \ubcf5\uc2b5':''}}
